const end = $now.setZone('Europe/Moscow').startOf('week');
const start = end.minus({ weeks: 1 });
const labels = ['bug', 'task', 'feature-request', 'needs-triage'];

return labels.map(label => ({
  json: {
    label,
    week_start: start.toISODate(),
    week_end_exclusive: end.toISODate(),
    query: [
      'repo:kamilasalis/ITMOv2',
      'is:issue',
      `label:"${label}"`,
      `created:${start.toUTC().toISO({ suppressMilliseconds: true })}..${end.minus({ seconds: 1 }).toUTC().toISO({ suppressMilliseconds: true })}`
    ].join(' ')
  }
}));

const queries = $('Code in JavaScript').all();
const responses = $input.all();
const byType = {};
const authors = new Map();
const seenIssues = new Set();

for (const [index, response] of responses.entries()) {
  const { label } = queries[index].json;
  const { items, total_count, incomplete_results } = response.json;

  if (incomplete_results || items.length !== total_count) {
    throw new Error(`GitHub вернул неполный список для метки ${label}`);
  }

  byType[label] = items.length;

  for (const issue of items) {
    if (seenIssues.has(issue.id)) continue;
    seenIssues.add(issue.id);

    const author = issue.user?.login ?? 'Неизвестный автор';
    authors.set(author, (authors.get(author) ?? 0) + 1);
  }
}

const { week_start, week_end_exclusive } = queries[0].json;

return [{
  json: {
    week_start,
    week_end_exclusive,
    total_issues: seenIssues.size,
    by_type: byType,
    by_author: Object.fromEntries(authors)
  }
}];

const report = $('Compare weeks').first().json;
const ai = $input.first().json;
const comment = ai.text ?? ai.output ?? '';

const lastDay = new Date(`${report.week_end_exclusive}T00:00:00Z`);
lastDay.setUTCDate(lastDay.getUTCDate() - 1);

const formatDate = date => date.split('-').reverse().join('.');
const period = `${formatDate(report.week_start)} — ${formatDate(lastDay.toISOString().slice(0, 10))}`;
const signed = value => value > 0 ? `+${value}` : String(value);

const escapeHtml = value => String(value)
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;');

function makeTable(heading, nameColumn, valueColumn, values) {
  const rows = Object.entries(values)
    .map(([name, value]) => `<tr><td>${escapeHtml(name)}</td><td>${escapeHtml(value)}</td></tr>`)
    .join('');

  return `
    <h3>${heading}</h3>
    <table border="1" cellpadding="6" cellspacing="0">
      <tr><th>${nameColumn}</th><th>${valueColumn}</th></tr>
      ${rows || '<tr><td colspan="2">Нет обращений</td></tr>'}
    </table>`;
}

const comparison = report.delta_total === null
  ? '<p>Данных за предыдущую неделю пока нет.</p>'
  : `<p>Общее изменение к прошлой неделе: <strong>${signed(report.delta_total)}</strong></p>
     ${makeTable('Изменение по типам', 'Тип', 'Δ', Object.fromEntries(
       Object.entries(report.delta_by_type).map(([type, delta]) => [type, signed(delta)])
     ))}`;

return [{
  json: {
    subject: `ITMOv2 — отчёт по Issues за ${period}`,
    html: `
      <h2>Еженедельный отчёт по GitHub Issues</h2>
      <p>Период: ${period}</p>
      <p>Всего обращений: <strong>${report.total_issues}</strong></p>
      ${makeTable('По типам', 'Тип', 'Обращений', report.by_type)}
      ${makeTable('По авторам', 'Автор', 'Обращений', report.by_author)}
      ${comparison}
      <h3>AI-комментарий недели</h3>
      <p>${escapeHtml(comment)}</p>
    `
  }
}];

const current = $('Group weekly issues').first().json;
const previous = $input.first().json;
const hasPrevious = Boolean(previous.week_start);

const previousByType = hasPrevious
  ? JSON.parse(previous.by_type_json)
  : {};

const deltaByType = hasPrevious
  ? Object.fromEntries(
      Object.entries(current.by_type).map(([type, count]) => [
        type, count - (previousByType[type] ?? 0)
      ])
    )
  : null;

return [{
  json: {
    ...current,
    previous_week_start: previous.week_start ?? null,
    delta_total: hasPrevious ? current.total_issues - previous.total_issues : null,
    delta_by_type: deltaByType
  }
}];

